package io.mac2phone.app;
import android.content.*;import android.net.nsd.*;import android.net.wifi.WifiManager;import android.os.*;import org.json.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
/** Foreground discovery and approval. Discovery never opens a capture session. */
public final class Nearby implements AutoCloseable {
 public interface UI {void devices(List<Device> devices);void incoming(Request request);void state(String text);void approved(String link);}
 public static final class Device {public final String id,name,platform;final InetAddress address;final int port;Device(String id,String name,String platform,InetAddress a,int p){this.id=id;this.name=name;this.platform=platform;address=a;port=p;}}
 public static final class Request {public final String name,platform,code;private final CompletableFuture<String> answer=new CompletableFuture<>();Request(String name,String platform,String code){this.name=name;this.platform=platform;this.code=code;}public void respond(String link){answer.complete(link);}}
 private final String id=UUID.randomUUID().toString(),name;private final UI ui;private final NsdManager nsd;private final WifiManager wifi;private WifiManager.MulticastLock multicast;private final Handler main=new Handler(Looper.getMainLooper());
 private final Map<String,Device> devices=new HashMap<>();private final Map<String,Long> recent=new HashMap<>();private final Set<Socket> sockets=ConcurrentHashMap.newKeySet();private ExecutorService workers;private volatile boolean active;private ServerSocket server;private volatile Socket outgoing;private volatile Request pending;
 private NsdManager.RegistrationListener registration;private NsdManager.DiscoveryListener discovery;private final ArrayDeque<NsdServiceInfo> resolutions=new ArrayDeque<>();private final Set<String> present=new HashSet<>();private boolean resolving;
 private long generation;
 public Nearby(Context context,UI ui){this.ui=ui;nsd=context.getSystemService(NsdManager.class);wifi=context.getApplicationContext().getSystemService(WifiManager.class);String value=Build.MODEL;name=NearbyCrypto.validName(value)?value:"Android";}
 public void start(){if(active)return;active=true;long epoch=++generation;workers=Executors.newFixedThreadPool(5);
  try{server=new ServerSocket(0);multicast=wifi.createMulticastLock("mac2phone-nearby");multicast.setReferenceCounted(false);multicast.acquire();NsdServiceInfo service=new NsdServiceInfo();service.setServiceName(name.substring(0,Math.min(24,name.length()))+" "+id.substring(0,8));service.setServiceType("_m2p-nearby._tcp.");service.setPort(server.getLocalPort());service.setAttribute("v","1");service.setAttribute("id",id);service.setAttribute("name",name);service.setAttribute("platform","android");
   registration=new NsdManager.RegistrationListener(){public void onServiceRegistered(NsdServiceInfo s){}public void onRegistrationFailed(NsdServiceInfo s,int e){state("Nearby advertising failed. Check local-network access.");}public void onServiceUnregistered(NsdServiceInfo s){}public void onUnregistrationFailed(NsdServiceInfo s,int e){}};nsd.registerService(service,NsdManager.PROTOCOL_DNS_SD,registration);
   discovery=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String t){}public void onDiscoveryStopped(String t){}public void onStartDiscoveryFailed(String t,int e){state("Nearby discovery is unavailable.");}public void onStopDiscoveryFailed(String t,int e){}
    public void onServiceFound(NsdServiceInfo s){main.post(()->{if(!active||generation!=epoch||present.size()>=128||!present.add(s.getServiceName()))return;resolutions.add(s);resolveNext(epoch);});}
    public void onServiceLost(NsdServiceInfo s){main.post(()->{if(generation!=epoch)return;present.remove(s.getServiceName());devices.remove(s.getServiceName());publish();});}};
   nsd.discoverServices("_m2p-nearby._tcp.",NsdManager.PROTOCOL_DNS_SD,discovery);
   ServerSocket bound=server;ExecutorService pool=workers;new Thread(()->{while(active&&generation==epoch)try{Socket s=bound.accept();if(sockets.size()>=4){s.close();continue;}sockets.add(s);pool.execute(()->accept(s,epoch));}catch(Exception e){break;}},"m2p-nearby-listener").start();
  }catch(Exception e){close();state("Nearby discovery needs Wi-Fi and local-network access.");}
 }
 private static String attr(NsdServiceInfo s,String key){byte[] b=s.getAttributes().get(key);return b==null?"":new String(b,StandardCharsets.UTF_8);}
 private void resolveNext(long epoch){if(resolving||resolutions.isEmpty()||!active||generation!=epoch)return;resolving=true;NsdServiceInfo next=resolutions.remove();
  try{nsd.resolveService(next,new NsdManager.ResolveListener(){private void done(NsdServiceInfo s){main.post(()->{if(generation!=epoch)return;resolving=false;if(s!=null&&present.contains(s.getServiceName())){try{String peer=attr(s,"id"),label=attr(s,"name"),platform=attr(s,"platform");UUID.fromString(peer);if(!peer.equals(id)&&attr(s,"v").equals("1")&&NearbyCrypto.validName(label)&&NearbyCrypto.platform(platform)&&s.getHost()!=null&&s.getPort()>0)devices.put(s.getServiceName(),new Device(peer,label,platform,s.getHost(),s.getPort()));}catch(Exception ignored){}publish();}resolveNext(epoch);});}public void onResolveFailed(NsdServiceInfo s,int e){done(null);}public void onServiceResolved(NsdServiceInfo s){done(s);}});}catch(Exception e){resolving=false;resolveNext(epoch);}
 }
 private void publish(){Map<String,Device> unique=new LinkedHashMap<>();for(Device device:devices.values())unique.put(device.id,device);List<Device> values=new ArrayList<>(unique.values());values.sort(Comparator.comparing(d->d.name));ui.devices(values);}
 private void state(String s){main.post(()->ui.state(s));}
 private static JSONObject read(Socket s)throws Exception{DataInputStream in=new DataInputStream(s.getInputStream());int n=in.readInt();if(n<2||n>4096)throw new IOException();byte[] bytes=new byte[n];in.readFully(bytes);return new JSONObject(new String(bytes,StandardCharsets.UTF_8));}
 private static void send(Socket s,JSONObject o)throws Exception{byte[] b=o.toString().getBytes(StandardCharsets.UTF_8);if(b.length>4096)throw new IOException();DataOutputStream out=new DataOutputStream(s.getOutputStream());out.writeInt(b.length);out.write(b);out.flush();}
 private void accept(Socket socket,long epoch){NearbyCrypto crypto=new NearbyCrypto();Request request=null;try{String address=socket.getInetAddress().getHostAddress();synchronized(recent){long now=System.currentTimeMillis();recent.entrySet().removeIf(e->now-e.getValue()>10000);if(recent.containsKey(address)||recent.size()>=128)throw new IOException();recent.put(address,now);}
  socket.setSoTimeout(8000);socket.setTcpNoDelay(true);JSONObject hello=read(socket);if(hello.optInt("v")!=1)throw new IOException();String label=hello.getString("name"),platform=hello.getString("platform");if(!NearbyCrypto.validName(label)||!NearbyCrypto.platform(platform))throw new IOException();byte[] commitment=NearbyCrypto.decode(hello.getString("commit"),32);
  send(socket,new JSONObject().put("v",1).put("key",crypto.publicKey));JSONObject reveal=read(socket);String clientKey=reveal.getString("key");byte[] nonce=NearbyCrypto.decode(reveal.getString("nonce"),32);
  if(!java.security.MessageDigest.isEqual(commitment,NearbyCrypto.decode(NearbyCrypto.commit(clientKey,nonce),32)))throw new IOException();crypto.agree(label,platform,clientKey,crypto.publicKey);
  synchronized(this){if(!active||epoch!=generation||pending!=null)throw new IOException();request=new Request(label,platform,crypto.code);pending=request;}
  socket.setSoTimeout(120000);Request shown=request;main.post(()->{if(active&&generation==epoch&&pending==shown)ui.incoming(shown);});
  // Watch for disconnect/cancel without blocking the bounded request workers.
  Thread monitor=new Thread(()->{try{socket.getInputStream().read();}catch(Exception ignored){}shown.respond(null);},"m2p-request-cancel");monitor.setDaemon(true);monitor.start();
  String link=request.answer.get(120,TimeUnit.SECONDS);if(!active||generation!=epoch)throw new IOException();JSONObject result=new JSONObject().put("status",link==null?"declined":"accepted");if(link!=null){Pairing.parse(link);result.put("link",link);}send(socket,new JSONObject().put("box",crypto.seal(result.toString())));
 }catch(Exception ignored){}finally{crypto.close();sockets.remove(socket);try{socket.close();}catch(Exception ignored){}Request old=request;synchronized(this){if(pending==old)pending=null;}main.post(()->{if(generation==epoch&&pending==null)ui.incoming(null);});}}
 public void request(Device device){if(!active||outgoing!=null)return;Socket socket=new Socket();outgoing=socket;long epoch=generation;workers.execute(()->{NearbyCrypto crypto=new NearbyCrypto();try{socket.connect(new InetSocketAddress(device.address,device.port),8000);socket.setSoTimeout(120000);byte[] nonce=NearbyCrypto.nonce();JSONObject hello=new JSONObject().put("v",1).put("name",name).put("platform","android").put("commit",NearbyCrypto.commit(crypto.publicKey,nonce));send(socket,hello);JSONObject challenge=read(socket);if(challenge.optInt("v")!=1)throw new IOException();crypto.agree(name,"android",crypto.publicKey,challenge.getString("key"));send(socket,new JSONObject().put("key",crypto.publicKey).put("nonce",Base64.getEncoder().encodeToString(nonce)));state("Waiting for "+device.name+". Compare code "+crypto.code+" on both screens.");JSONObject result=new JSONObject(crypto.open(read(socket).getString("box")));if(!result.optString("status").equals("accepted")){state("Request declined.");return;}Pairing received=Pairing.parse(result.getString("link"));Pairing routed=new Pairing(device.address.getHostAddress(),received.port,received.identity,received.key);routed.ticket=received.ticket;String link=routed.link();main.post(()->{if(active&&generation==epoch)ui.approved(link);});}catch(Exception e){state("Request ended. Check the other device and try again.");}finally{crypto.close();try{socket.close();}catch(Exception ignored){}if(outgoing==socket)outgoing=null;}});}
 public void cancel(){Socket old=outgoing;outgoing=null;if(old!=null)try{old.close();}catch(Exception ignored){}}
 public void close(){active=false;++generation;cancel();Request old=pending;pending=null;if(old!=null)old.respond(null);for(Socket socket:sockets)try{socket.close();}catch(Exception ignored){}sockets.clear();try{if(server!=null)server.close();}catch(Exception ignored){}server=null;
  try{if(discovery!=null)nsd.stopServiceDiscovery(discovery);}catch(Exception ignored){}try{if(registration!=null)nsd.unregisterService(registration);}catch(Exception ignored){}discovery=null;registration=null;if(multicast!=null&&multicast.isHeld())multicast.release();multicast=null;if(workers!=null)workers.shutdownNow();devices.clear();resolutions.clear();present.clear();resolving=false;publish();ui.incoming(null);}
}
